const bySlug = new Map(propertyDetails.map((property) => [property.slug, property]));
const byId = new Map(propertyDetails.map((property) => [property.id, property]));
const byTitle = new Map(
  propertyDetails.map((property) => [property.title.toLowerCase(), property])
);

export function getPropertyBySlug(slug: string): PropertyDetail | undefined {
  return bySlug.get(slug);
}

export function getPropertyById(id: number): PropertyDetail | undefined {
  return byId.get(id);
}

/** Resolves a listing card title (any casing) to its detail-page path. */
export function propertyHref(title: string): string | undefined {
  const match = byTitle.get(title.toLowerCase());
  return match ? `/properties/${match.slug}` : undefined;
}
